import {parseCSV,recommend,quote,eligible,removeWithDependants,extractFields,checkKYC,mask,TODAY,transition,validateProfile} from './core.mjs';
const $=s=>document.querySelector(s),money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const [catalogue,gstRows,udyamRows]=await Promise.all(['product_catalogue.csv','mock_gstin_registry.csv','mock_udyam_registry.csv'].map(async f=>parseCSV(await(await fetch('data/'+f)).text())));
const state={step:0,sample:'K09',language:'en',profile:{segment:'prof',employees:5,sites:1,tier:2,budget:3500,currentTools:'home',priority:'uptime',hasGst:true,language:'en'},bundle:null,explanation:'',mode:'offline',consent:false,docs:{},gstin:'',udyam:'',confirmed:false,kyc:null,busy:false,order:null};
try{const saved=JSON.parse(localStorage.getItem('udyam.order'));if(saved&&Date.now()-saved.savedAt<86400000){state.order=saved;state.step=3;}else localStorage.removeItem('udyam.order');}catch{}
const hi=()=>state.language==='hi';const tr=(en,hindi)=>hi()?hindi:en;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,5500);}
function nav(){const labels=hi()?['सलाहकार','पैकेज और कीमत','दस्तावेज़ जाँच','ऑर्डर ट्रैकर']:['Business advisor','Your quote','Smart KYC','Order tracker'];$('#steps').innerHTML=labels.map((l,i)=>`<button class="step ${i===state.step?'active':''}" data-step="${i}" ${state.busy?'disabled':''}><span>${i+1}</span>${l}</button>`).join('');document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const i=+b.dataset.step;if(i===1&&!state.bundle)return toast('Complete the business advisor first.');if(i===2&&(!state.bundle||quote(catalogue,state.bundle,state.profile).errors.length))return toast('Build a valid quote first.');if(i===3&&!state.order)return toast('Complete KYC and demo checkout first.');state.step=i;render();});}
const title=(n,t,desc)=>`<div class="eyebrow">${n} / UDYAM DIGITAL</div><h1>${t}</h1><p class="intro">${desc}</p>`;
function render(){nav();if(state.step===0)advisor();if(state.step===1)quotePage();if(state.step===2)kycPage();if(state.step===3)tracker();}
function advisor(){
 $('#main').innerHTML=title('01',tr('What does your business need?','आपके व्यवसाय को क्या चाहिए?'),tr('Tell us a little about your business. We’ll suggest a clear, editable bundle from the catalogue.','अपने व्यवसाय के बारे में बताएं। हम कैटलॉग से आपके लिए एक पैकेज सुझाएंगे।'))+`<div class="grid"><section class="panel"><h2>${tr('A few questions, a better fit','कुछ सवाल, बेहतर सुझाव')}</h2><form id="profile"><div class="fields"><label class="field full">${tr('What kind of business do you run?','आपका व्यवसाय किस प्रकार का है?')}<select name="segment"><option value="prof">Professional office / clinic</option><option value="micro">Micro retail / services</option><option value="multi">Small multi-site business</option><option value="mfg">Small manufacturer</option></select></label><label class="field">${tr('People on your team','कर्मचारियों की संख्या')}<input name="employees" type="number" min="1" max="1000" required value="${state.profile.employees}"></label><label class="field">${tr('Business locations','व्यवसाय के स्थान')}<input name="sites" type="number" min="1" max="1000" required value="${state.profile.sites}"></label><label class="field">${tr('City tier','शहर की श्रेणी')}<select name="tier"><option value="1">Tier 1</option><option value="2">Tier 2</option></select></label><label class="field">${tr('Monthly budget, before tax','मासिक बजट, कर से पहले')}<input name="budget" type="number" min="1" required value="${state.profile.budget}"></label><label class="field">Current internet<select name="currentTools"><option value="home">Home broadband</option><option value="hotspot">Mobile hotspot</option><option value="business">Business connection</option></select></label><label class="field">Main priority<select name="priority"><option value="uptime">Avoid outages</option><option value="lowest_cost">Lowest monthly cost</option><option value="productivity">Email and productivity</option></select></label></div><label class="check"><input name="hasGst" type="checkbox" ${state.profile.hasGst?'checked':''}>${tr('My business has a GSTIN. We will verify its status during KYC.','मेरे व्यवसाय के पास GSTIN है। KYC में इसकी स्थिति जाँची जाएगी।')}</label><div class="actions"><button class="primary" type="submit" id="recommend">${tr('Find my bundle','मेरा पैकेज खोजें')}</button><button class="quiet" type="button" id="example">Use 5-person office example</button></div></form><p class="note">No contact or identity details are needed at this stage. Catalogue prices are fictional.</p></section><section class="panel red"><span class="badge" id="ai-mode">${tr('Ready to recommend','सुझाव देने के लिए तैयार')}</span><h2 style="margin-top:20px">${tr('A bundle you can understand','एक स्पष्ट पैकेज')}</h2><div class="answer" id="advice">${esc(state.explanation||tr('Start with your team size, locations and budget. The price engine checks the catalogue before anything reaches your quote.','अपनी टीम, स्थान और बजट से शुरू करें। कीमतें और पात्रता कैटलॉग के नियमों से तय होती हैं।'))}</div><hr class="rule"><ul class="list"><li>See monthly price, setup and contract together.</li><li>Choose only the add-ons you need.</li><li>Get a clear reason when a partner needs to help.</li></ul><p class="note">Live AI can explain a rule-approved recommendation when a local server key is configured. It cannot set prices or approve KYC.</p></section></div>`;
 $('#profile [name=segment]').value=state.profile.segment;$('#profile [name=tier]').value=state.profile.tier;$('#profile [name=currentTools]').value=state.profile.currentTools||'home';$('#profile [name=priority]').value=state.profile.priority||'uptime';
 $('#example').onclick=()=>{state.profile={segment:'prof',employees:5,sites:1,tier:2,budget:3500,currentTools:'home',priority:'uptime',hasGst:true,language:state.language};advisor();};
 $('#profile').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const p={segment:f.get('segment'),employees:+f.get('employees'),sites:+f.get('sites'),tier:+f.get('tier'),budget:+f.get('budget'),currentTools:f.get('currentTools'),priority:f.get('priority'),hasGst:f.has('hasGst'),language:state.language};const errors=validateProfile(p);if(errors.length)return toast(errors.join(' '));state.profile=p;state.bundle=recommend(catalogue,p).bundle;state.kyc=null;state.busy=true;$('#recommend').disabled=true;$('#recommend').textContent='Checking the catalogue…';let result={mode:'offline',explanation:recommend(catalogue,p).reason};try{const r=await fetch('/api/advice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});if(r.ok)result=await r.json();}catch{}state.mode=result.mode;state.explanation=result.explanation;state.aiNotice=result.notice||'';state.busy=false;state.step=1;render();};
}
function quotePage(){const q=quote(catalogue,state.bundle,state.profile);const available=catalogue.filter(p=>!state.bundle[p.product_id]);
 $('#main').innerHTML=title('02',tr('Your bundle. Your choice.','आपका पैकेज। आपकी पसंद।'),tr('Adjust quantities or add products. Every change recalculates the quote and checks eligibility.','उत्पाद जोड़ें या संख्या बदलें। हर बदलाव पर कीमत और पात्रता फिर जाँची जाती है।'))+`<div class="grid"><section class="panel"><h2>${tr('Recommended for your business','आपके व्यवसाय के लिए सुझाव')}</h2><span class="badge ${state.mode==='genai'?'green':''}">${state.mode==='genai'?'Live GenAI explanation':state.mode==='fallback'?'AI unavailable · offline fallback':'Offline rules explanation'}</span>${state.aiNotice?`<p class="warning" role="status">${esc(state.aiNotice)}</p>`:''}<p class="answer" style="font-size:14px">${esc(state.explanation)}</p><div id="products">${q.lines.map(l=>`<div class="product"><div><strong>${esc(l.product_name)}</strong><small>${l.product_id} · ${esc(l.unit)} · ${money(l.price_min_inr_per_month)} each</small></div><input type="number" min="1" max="1000" value="${l.qty}" data-qty="${l.product_id}" aria-label="Quantity for ${esc(l.product_name)}"><div class="amount">${money(l.monthly)}</div><button data-remove="${l.product_id}" aria-label="Remove ${esc(l.product_name)}">×</button></div>`).join('')}</div><div class="quote-tools"><select id="add-product" aria-label="Add a product">${available.map(p=>`<option value="${p.product_id}" ${eligible(p,state.profile).length?'disabled':''}>${p.product_name} (+${money(p.price_min_inr_per_month)})${eligible(p,state.profile).length?' — ineligible':''}</option>`).join('')}</select><button class="outline small" id="add">Add</button></div><p class="note">Removing a required connection also removes dependent add-ons. GST-dependent products remain provisional until registry verification.</p></section><section class="panel"><h2>${tr('One transparent quote','स्पष्ट कीमत')}</h2><div class="price">${money(q.total)}<small> / month incl. demo tax</small></div><div class="metric-row"><span>Monthly products</span><b>${money(q.subtotal)}</b></div><div class="metric-row"><span>Demo tax assumption (18%)</span><b>${money(q.tax)}</b></div><div class="metric-row"><span>One-time setup, before tax</span><b>${money(q.setup)}</b></div><div class="metric-row"><span>Setup tax assumption (18%)</span><b>${money(q.setupTax)}</b></div><div class="metric-row total"><span>First payment</span><span>${money(q.firstPayment)}</span></div><div class="term"><span><b>${q.contract} months</b>Bundle commitment</span><span><b>${q.installDays} days typical</b>After clearance, subject to slot</span></div>${q.overBudget?'<p class="warning">Above your stated pre-tax budget. Adjust the bundle or confirm your choice below.</p>':''}${q.errors.length?'<p class="error">'+q.errors.map(esc).join('<br>')+'</p>':''}<label class="check"><input id="terms" type="checkbox">I understand the demo tax assumption, setup fee, commitment and installation estimate. No real payment will be taken.</label><button class="primary wide" id="checkout" ${q.errors.length?'disabled':''}>${tr('Continue to Smart KYC','दस्तावेज़ जाँच पर जाएँ')}</button><button class="quiet wide" id="download-quote">Download itemised quote</button><p class="note">Minimum catalogue prices. Tax, serviceability and commercial terms require confirmation for a real order.</p></section></div>`;
 document.querySelectorAll('[data-qty]').forEach(e=>e.onchange=()=>{state.bundle[e.dataset.qty]=+e.value;state.kyc=null;quotePage();});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.bundle=removeWithDependants(catalogue,state.bundle,b.dataset.remove);state.kyc=null;quotePage();});$('#add').onclick=()=>{const id=$('#add-product').value;if(id){state.bundle[id]=1;state.kyc=null;quotePage();}};$('#checkout').onclick=()=>{if(!$('#terms').checked)return toast('Please acknowledge the quote terms.');state.step=2;render();};$('#download-quote').onclick=()=>download('Udyam_Quote.json',{...q,notice:'Synthetic quote. 18% tax is a demo assumption. Not an invoice.'});
}
const docNames={gst:'GST certificate',udyam:'Udyam certificate',id:'Signatory ID',address:'Address proof'};
function docHTML(kind){const d=state.docs[kind];return`<div class="doc ${d?'ready':''}"><h3>${docNames[kind]}</h3><p>${d?'Extracted · '+Math.round(d.confidence)+'% OCR confidence':'PNG or JPG, up to 8 MB'}</p><input type="file" accept="image/png,image/jpeg" data-upload="${kind}" aria-label="Upload ${docNames[kind]}" ${state.busy?'disabled':''}>${d?`<details><summary>Review extracted fields</summary>${Object.entries(d).filter(([k])=>!['text','confidence'].includes(k)).map(([k,v])=>`<label class="field">${k}<input data-doc="${kind}" data-field="${k}" value="${esc(v)}"></label>`).join('')}<details><summary>OCR text</summary><pre style="white-space:pre-wrap;font-size:10px;max-height:180px;overflow:auto">${esc(d.text)}</pre></details></details>`:''}</div>`;}
function kycPage(){
 $('#main').innerHTML=title('03',tr('Less paperwork. More clarity.','कम कागज़ी काम। अधिक स्पष्टता।'),tr('Give consent, extract your documents and review the fields before verification.','सहमति दें, दस्तावेज़ पढ़ें और जाँच से पहले निकाली गई जानकारी की पुष्टि करें।'))+`<div class="grid"><section class="panel"><h2>${tr('Your documents stay in this browser','आपके दस्तावेज़ इसी ब्राउज़र में रहते हैं')}</h2><div class="consent-copy"><p>${tr('We use documents only to check business identity and prepare this demo order. Raw images are processed locally and never sent to the AI model.','हम दस्तावेज़ों का उपयोग केवल व्यवसाय की जाँच और डेमो ऑर्डर के लिए करते हैं। चित्र स्थानीय रूप से पढ़े जाते हैं, AI मॉडल को नहीं भेजे जाते।')}</p><p>Uploaded images and extracted fields are held in memory for this session. A masked order summary expires after 24 hours. Reset or withdrawal deletes the saved demo state. No marketing consent is requested.</p></div><label class="check"><input id="consent" type="checkbox" ${state.consent?'checked':''} ${state.busy?'disabled':''}>${tr('I consent to processing fictional documents for this demo.','मैं इस डेमो में काल्पनिक दस्तावेज़ों की जाँच के लिए सहमति देता/देती हूँ।')}</label>${state.consent?`<div class="fields"><label class="field">GSTIN (synthetic)<input id="gstin" value="${esc(state.gstin)}" maxlength="15" autocomplete="off" ${state.profile.hasGst?'':'disabled'}></label><label class="field">Udyam number (optional)<input id="udyam" value="${esc(state.udyam)}" autocomplete="off"></label></div><div class="actions"><select id="sample-select" aria-label="Sample applicant" style="width:130px">${Array.from({length:12},(_,i)=>'<option value="K'+String(i+1).padStart(2,'0')+'"'+(state.sample==='K'+String(i+1).padStart(2,'0')?' selected':'')+'>Sample K'+String(i+1).padStart(2,'0')+'</option>').join('')}</select><button class="outline small" id="sample" ${state.busy?'disabled':''}>Extract sample documents</button><button class="quiet small danger" id="withdraw" ${state.busy?'disabled':''}>Withdraw and erase</button></div><p class="note">K09 demonstrates a clean record. K01 has a cancelled GST registration. OCR reads actual supplied images, not prefilled answers.</p><div id="ocr-progress">${state.busy?'<span class="spinner"></span>Reading documents…':''}</div><div class="documents">${['gst','udyam','id','address'].map(docHTML).join('')}</div><label class="check"><input id="confirmed" type="checkbox" ${state.confirmed?'checked':''} ${state.busy?'disabled':''}>I have reviewed the extracted fields against the documents.</label><button class="primary" id="verify" ${state.busy?'disabled':''}>Verify against mock registries</button>`:'<div class="warning">Document upload and lookup are locked until you give consent.</div>'}</section><section class="panel soft"><h2>Verification, explained</h2><div id="kyc-result">${kycResult()}</div><hr class="rule"><ul class="list"><li>GST checksum and active status</li><li>Cross-document business name checks</li><li>Address date and postcode checks</li><li>Signatory ID expiry and OCR confidence</li></ul><p class="note">Exercise date: ${TODAY}. Registry data is mocked. Name consistency does not establish signatory authority. Real telecom KYC requires further checks.</p></section></div>`;
 $('#consent').onchange=e=>{state.consent=e.target.checked;if(!state.consent)eraseKYC();kycPage();};if(!state.consent)return;
 $('#gstin').onchange=e=>{state.gstin=e.target.value.trim().toUpperCase();state.kyc=null;};$('#udyam').onchange=e=>{state.udyam=e.target.value.trim().toUpperCase();state.kyc=null;};$('#confirmed').onchange=e=>state.confirmed=e.target.checked;
 $('#withdraw').onclick=()=>{eraseKYC();state.consent=false;state.order=null;localStorage.removeItem('udyam.order');kycPage();toast('Consent withdrawn. Local documents and saved demo order erased.');};
 document.querySelectorAll('[data-upload]').forEach(e=>e.onchange=async()=>{const f=e.files[0];if(f)await ocrFiles([[e.dataset.upload,f]]);});
 document.querySelectorAll('[data-doc]').forEach(e=>e.onchange=()=>{state.docs[e.dataset.doc][e.dataset.field]=e.value.trim();state.kyc=null;state.confirmed=false;$('#confirmed').checked=false;});
 $('#sample-select').onchange=e=>state.sample=e.target.value;$('#sample').onclick=async()=>{state.docs={};state.gstin='';state.udyam='';try{const files=await Promise.all(Object.entries({gst:'gst_certificate',udyam:'udyam_certificate',id:'signatory_id',address:'address_proof'}).map(async([k,n])=>[k,await(await fetch(`samples/${state.sample}_${n}.png`)).blob()]));await ocrFiles(files);}catch{toast('Could not read the supplied sample files.');}};
 $('#verify').onclick=()=>{state.gstin=$('#gstin').value.trim().toUpperCase();state.udyam=$('#udyam').value.trim().toUpperCase();state.kyc=checkKYC({...state,hasGst:state.profile.hasGst},gstRows,udyamRows);const q=quote(catalogue,state.bundle,state.profile,{strict:true,gstStatus:state.kyc.gstStatus});if(q.errors.length){state.kyc.issues.push(...q.errors);state.kyc.status='review';}kycPage();};
 if($('#create-order'))$('#create-order').onclick=()=>placeOrder(false);if($('#simulate-fail'))$('#simulate-fail').onclick=()=>placeOrder(true);if($('#review'))$('#review').onclick=()=>toast('Demo review case created. A partner would receive the masked reference and exception reasons.');
}
function kycResult(){if(!state.kyc)return'<p class="subtle">Your result appears here after you review and verify the documents.</p>';const k=state.kyc;if(k.status!=='verified_demo')return`<div class="warning"><b>Needs human review</b><ul>${k.issues.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></div><button id="review" class="outline wide" style="margin-top:15px">Create demo review case</button>`;return`<div class="success"><b>Demo checks passed</b><p>${esc(k.business)}<br>GST: ${esc(k.maskedGST)}</p></div><p class="note">These checks are a prototype gate, not statutory KYC approval. Payment below is simulated.</p><button id="create-order" class="primary wide">Simulate successful payment</button><button id="simulate-fail" class="quiet wide">Test payment failure</button>`;}
async function ocrFiles(files){if(!state.consent)return;state.busy=true;state.kyc=null;state.confirmed=false;kycPage();let worker;try{worker=await Tesseract.createWorker('eng',1,{workerPath:new URL('./vendor/worker.min.js',location.href).href,corePath:new URL('./vendor/core/',location.href).href,langPath:new URL('./vendor/',location.href).href,logger:m=>{const el=$('#ocr-progress');if(el)el.textContent=(m.status||'Reading')+(m.progress?' '+Math.round(m.progress*100)+'%':'');}});for(const[k,f]of files){if(f.size>8*1024*1024||!['image/png','image/jpeg'].includes(f.type))throw new Error('Use PNG or JPG images smaller than 8 MB.');const {data}=await worker.recognize(f);state.docs[k]={...extractFields(data.text,k),confidence:data.confidence};if(k==='gst'&&state.docs[k].gstin)state.gstin=state.docs[k].gstin;if(k==='udyam'&&state.docs[k].udyam)state.udyam=state.docs[k].udyam;}}catch(e){toast('OCR could not finish: '+e.message);}finally{if(worker)await worker.terminate();state.busy=false;kycPage();}}
function eraseKYC(){state.docs={};state.gstin='';state.udyam='';state.confirmed=false;state.kyc=null;}
function placeOrder(fail){if(!state.kyc||state.kyc.status!=='verified_demo')return;if(state.order){state.step=3;return render();}const q=quote(catalogue,state.bundle,state.profile,{strict:true,gstStatus:state.kyc.gstStatus});if(q.errors.length)return toast(q.errors.join(' '));state.order={id:'UD-'+crypto.randomUUID().slice(0,8).toUpperCase(),status:fail?'payment_failed':'submitted',savedAt:Date.now(),total:q.total,firstPayment:q.firstPayment,installDays:q.installDays,products:q.lines.map(l=>({name:l.product_name,qty:l.qty,days:+l.typical_install_days})),maskedGST:mask(state.gstin),events:[{name:fail?'Payment failed (simulation)':'Order submitted (simulation)',time:new Date().toISOString()}]};saveOrder();state.step=3;eraseKYC();render();}
function saveOrder(){localStorage.setItem('udyam.order',JSON.stringify(state.order));}
function tracker(){const o=state.order;const flow=['submitted','site_check','scheduled','active'],current=flow.indexOf(o.status),labels=['Order received','Site feasibility check','Installation scheduled','Services activated'];
 $('#main').innerHTML=title('04',tr('You should never have to chase an update.','हर अपडेट, एक ही जगह।'),tr('Track every step, see what happens next and know when a partner needs to help.','हर चरण की स्थिति देखें और जानें कि अगला कदम क्या है।'))+`<div class="grid"><section class="panel"><div class="metric-row"><h2>Your order</h2><span class="badge ${o.status==='active'?'green':''}">${o.status==='active'?'Active (simulated)':'Demo order'}</span></div><div class="orderid">${o.id}</div>${o.status==='payment_failed'?'<div class="error" style="margin-top:20px">Demo payment failed. No money was charged. Retry will reuse this order reference.</div><button id="retry" class="primary" style="margin-top:15px">Retry demo payment</button>':`<ol class="timeline">${labels.map((l,i)=>`<li class="${i<=current?'done':''} ${i===current?'current':''}">${l}<small>${i<current?'Completed in simulation':i===current?(o.delayed?'Delayed. Partner to confirm a revised slot.':'Current stage'):'Not yet started'}</small></li>`).join('')}</ol>`}${o.delayed?'<div class="warning">Installation delay simulated. Revised estimate: 2 additional days. Assigned team: Demo Local Partner.</div>':''}<details class="sim" open><summary>Demo event simulator</summary><p class="note">These controls simulate partner events. They do not represent real installation progress.</p><div class="actions"><button id="advance" class="outline small" ${current<0||current>=3?'disabled':''}>Next installation event</button><button id="delay" class="outline small" ${!['site_check','scheduled'].includes(o.status)?'disabled':''}>Simulate delay</button></div></details></section><section class="panel"><h2>Order summary</h2><div class="price">${money(o.total)}<small> / month</small></div><div class="metric-row"><span>First demo payment</span><b>${money(o.firstPayment)}</b></div><p class="note">Typical installation: ${o.installDays} days after clearance, subject to a confirmed slot. Mock GST reference: ${esc(o.maskedGST)}.</p><hr class="rule">${o.products.map(l=>`<div class="metric-row"><span>${esc(l.name)} × ${l.qty}</span><b>${o.status==='active'?'Active':'Pending'}</b></div>`).join('')}<button class="outline wide" id="order-download">Download masked order receipt</button><details style="margin-top:20px"><summary>Event history</summary><ul class="list">${o.events.map(e=>'<li>'+esc(e.name)+'<br><small>'+new Date(e.time).toLocaleTimeString()+'</small></li>').join('')}</ul></details></section></div>`;
 $('#advance').onclick=()=>event('next','Installation stage advanced (simulation)');$('#delay').onclick=()=>event('delay','Installation delay (simulation)');if($('#retry'))$('#retry').onclick=()=>event('retry_payment','Payment retry succeeded (simulation)');$('#order-download').onclick=()=>download(o.id+'.json',o);
}
function event(type,name){state.order=transition(state.order,type);state.order.events.push({name,time:new Date().toISOString()});saveOrder();tracker();}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#language').onchange=e=>{state.language=e.target.value;state.profile.language=state.language;document.documentElement.lang=state.language;render();};$('#reset').onclick=()=>{if(state.busy)return toast('Wait for document extraction to finish.');localStorage.removeItem('udyam.order');eraseKYC();state.order=null;state.bundle=null;state.consent=false;state.step=0;state.explanation='';render();};$('#help').onclick=()=>toast('Demo assistance request captured. A production partner queue would receive a masked reference, not your raw documents.');render();
